content.text:
{
  "name": "微米级位移测量仪",
  "name_en": "Micrometer-Scale Displacement Meter",
  "manufacturer": "",
  "description": "一种通过命令通信获取测量值和设备信息的位移测量设备，支持设置读数单位缩放，适合实验中读取位移、距离或类似单值尺寸信号。",
  "description_en": "A displacement measurement instrument accessed through command-based communication, supporting reading retrieval, device information queries, and unit scaling. It is suitable for laboratory measurement of displacement, distance, or similar single-value dimensional signals.",
  "actions": [
    {
      "action_name": "auto-set_unit_scale",
      "description": "设置读数单位缩放比例",
      "description_en": "Set the reading unit scale."
    },
    {
      "action_name": "auto-send_cmd",
      "description": "发送设备命令",
      "description_en": "Send a command to the device."
    },
    {
      "action_name": "auto-request_read",
      "description": "请求一次测量读数",
      "description_en": "Request a measurement reading."
    },
    {
      "action_name": "auto-request_device_info",
      "description": "请求设备信息",
      "description_en": "Request device information."
    },
    {
      "action_name": "auto-get_reading",
      "description": "获取测量读数",
      "description_en": "Get the measurement reading."
    },
    {
      "action_name": "auto-get_device_info",
      "description": "获取设备信息",
      "description_en": "Get device information."
    },
    {
      "action_name": "auto-check_resp",
      "description": "检查设备响应是否有效",
      "description_en": "Check whether the device response is valid."
    }
  ],
  "tag_hints": [
    "displacement measurement",
    "distance sensing",
    "micrometer resolution",
    "serial command protocol",
    "device information query"
  ]
}

